/** A creature's kind, if one is drawn for it. */
export const kindOf = (id: string): Kind | undefined => KIND[id];

/** A kind's portrait as one path, body and eyes, for a canvas to stroke. */
export const portraitPath = (kind: Kind) => [...PORTRAIT[kind].body, ...PORTRAIT[kind].eyes].join('');

export type Tone = 'foe' | 'red' | 'shadow';

/**
 * A creature's portrait, in its tone: `foe` in the colour it is set in, its eyes red; `red` red, its eyes white-hot;
 * `shadow` dark, rimmed in violet, its eyes violet. Every creature has one (`tests/portraits.test.ts`).
 */
export function Portrait({ id, size = 24, tone = 'foe', class: cls }: { id: string; size?: number; tone?: Tone; class?: string }) {
  const kind = kindOf(id);
  const e = enemyById(id);
  if (!kind) return null;
  const p = PORTRAIT[kind];
  return (
    <svg viewBox="0 0 24 24" width={size} height={size} class={`cface is-${tone} ${cls ?? ''}`} data-kind={kind} role="img" aria-label={e?.name ?? kind}>
      <g class="cface__body">{p.body.map((d, i) => <path key={i} d={d} fill-rule="evenodd" />)}</g>
      <g class="cface__eyes">{p.eyes.map((d, i) => <path key={i} d={d} />)}</g>
    </svg>
  );
}
